package storage

import (
	"github.com/TrebuchetDynamics/gormes-agent/internal/gateway/directory/storage/codec"
	"github.com/TrebuchetDynamics/gormes-agent/internal/gateway/directory/storage/decode"
	"github.com/TrebuchetDynamics/gormes-agent/internal/gateway/directory/storage/persisted"
)

// Root is the shared caller-owned persistence root contract for directory
// stores. It centralizes root normalization, file path construction, and empty
// root validation across cache and remembered-source stores.
type Root = persisted.Root

// NewRoot returns a normalized caller-owned persistence root.
func NewRoot(root string) Root { return persisted.NewRoot(root) }

// Spec names one persisted JSON file used by a directory store. It centralizes
// file names, temp-file patterns, and root-validation labels so stores can
// share persistence metadata without each rebuilding the same contract.
type Spec = persisted.Spec

// File is the shared persisted-JSON file contract for directory stores. It
// keeps path construction, root validation, and atomic-write metadata together
// so cache and source stores do not each rebuild that policy.
type File = persisted.File

// NewFile returns a persisted JSON file rooted at root.
func NewFile(root, name, tmpPattern, label string) File {
	return persisted.NewFile(root, name, tmpPattern, label)
}

// LoadValue reads a persisted JSON value using a caller-supplied empty value
// and post-decode normalization hook. Directory stores use this to share the
// same decode lifecycle while keeping their own missing/invalid evidence policy.
func LoadValue[T any](file File, empty func() T, ensure func(T) T) (T, error) {
	return decode.LoadValue(file, empty, ensure)
}

// Writer is the injectable write seam used by stores that need deterministic
// atomic-write failure tests.
type Writer = codec.Writer

// ReadJSON reads path into value using the stores' shared JSON decoding seam.
func ReadJSON(path string, value any) error { return codec.ReadJSON(path, value) }

// WriteAtomicJSON marshals value as indented JSON and atomically replaces name
// under root. The temporary file is created in root so rename stays atomic on
// normal local filesystems.
func WriteAtomicJSON(root, name, tmpPattern string, value any, writer Writer) error {
	return codec.WriteAtomicJSON(root, name, tmpPattern, value, writer)
}

package storage

import (
	"os"
	"path/filepath"
	"testing"
)

type facadeLoadValueFixture struct {
	Name string `json:"name"`
}

func TestFacadePreservesFileSpecAndLoadValueContract(t *testing.T) {
	root := t.TempDir()
	file := Spec{Name: "fixture.json", TmpPattern: ".fixture-*.tmp", Label: "fixture"}.Apply(File{Root: NewRoot(" " + root + " ")})
	if file.Root.String() != root {
		t.Fatalf("Root = %q, want trimmed temp root", file.Root.String())
	}
	if file.Name != "fixture.json" || file.TmpPattern != ".fixture-*.tmp" || file.Label != "fixture" {
		t.Fatalf("file metadata = %+v, want spec metadata", file)
	}
	if err := os.WriteFile(filepath.Join(root, "fixture.json"), []byte(`{"name":"raw"}`), 0o600); err != nil {
		t.Fatalf("write fixture: %v", err)
	}

	got, err := LoadValue(file, func() facadeLoadValueFixture { return facadeLoadValueFixture{Name: "empty"} }, func(value facadeLoadValueFixture) facadeLoadValueFixture {
		value.Name += ":ensured"
		return value
	})
	if err != nil {
		t.Fatalf("LoadValue error: %v", err)
	}
	if got.Name != "raw:ensured" {
		t.Fatalf("LoadValue Name = %q, want ensured decoded value", got.Name)
	}
}

package codec

import (
	"context"
	"path/filepath"

	"github.com/TrebuchetDynamics/gormes-agent/internal/gateway/jsonfile"
)

// Writer is the injectable write seam used by stores that need deterministic
// atomic-write failure tests.
type Writer = jsonfile.Writer

// ReadJSON reads path into value using the stores' shared JSON decoding seam.
func ReadJSON(path string, value any) error {
	return jsonfile.ReadRequired(context.Background(), path, value, "directory json")
}

// WriteAtomicJSON marshals value as indented JSON and atomically replaces name
// under root. The temporary file is created in root so rename stays atomic on
// normal local filesystems.
func WriteAtomicJSON(root, name, tmpPattern string, value any, writer Writer) error {
	return jsonfile.WriteAtomicWithOptions(context.Background(), filepath.Join(root, name), value, name, jsonfile.WriteOptions{
		DirMode:    0o700,
		FileMode:   0o600,
		TmpPattern: tmpPattern,
		Writer:     writer,
	})
}

package decode

// Reader is the persisted-value read seam required by LoadValue.
type Reader interface {
	Read(value any) error
}

// LoadValue reads a persisted JSON value using a caller-supplied empty value
// and post-decode normalization hook. Directory stores use this to share the
// same decode lifecycle while keeping their own missing/invalid evidence policy.
func LoadValue[T any](reader Reader, empty func() T, ensure func(T) T) (T, error) {
	value := zeroOrEmpty(empty)
	if err := reader.Read(&value); err != nil {
		return zeroOrEmpty(empty), err
	}
	if ensure != nil {
		value = ensure(value)
	}
	return value, nil
}

func zeroOrEmpty[T any](empty func() T) T {
	if empty != nil {
		return empty()
	}
	var value T
	return value
}

package persisted

import (
	"fmt"
	"path/filepath"
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/gateway/directory/storage/codec"
)

// Root is the shared caller-owned persistence root contract for directory
// stores. It centralizes root normalization, file path construction, and empty
// root validation across cache and remembered-source stores.
type Root string

// NewRoot returns a normalized caller-owned persistence root.
func NewRoot(root string) Root {
	return Root(strings.TrimSpace(root))
}

func (r Root) String() string { return string(r) }

// Path returns the path to name under the normalized root.
func (r Root) Path(name string) string {
	return filepath.Join(string(r), name)
}

// Require returns a store-specific empty-root error when the root is not set.
func (r Root) Require(label string) error {
	if strings.TrimSpace(string(r)) == "" {
		return fmt.Errorf("%s root is empty", label)
	}
	return nil
}

// Spec names one persisted JSON file used by a directory store. It centralizes
// file names, temp-file patterns, and root-validation labels so stores can
// share persistence metadata without each rebuilding the same contract.
type Spec struct {
	Name       string
	TmpPattern string
	Label      string
}

// File returns a persisted JSON file for root using the spec metadata.
func (s Spec) File(root string) File {
	return File{Root: NewRoot(root), Name: s.Name, TmpPattern: s.TmpPattern, Label: s.Label}
}

// Apply returns f when it is already configured, otherwise it builds the spec's
// default persisted JSON file while preserving any root carried by f.
func (s Spec) Apply(f File) File {
	if f.Name != "" {
		return f
	}
	return s.File(f.Root.String())
}

// File is the shared persisted-JSON file contract for directory stores. It
// keeps path construction, root validation, and atomic-write metadata together
// so cache and source stores do not each rebuild that policy.
type File struct {
	Root       Root
	Name       string
	TmpPattern string
	Label      string
}

// NewFile returns a persisted JSON file rooted at root.
func NewFile(root, name, tmpPattern, label string) File {
	return Spec{Name: name, TmpPattern: tmpPattern, Label: label}.File(root)
}

// WithDefaults returns f when it is already configured, otherwise it builds the
// store's default persisted JSON file while preserving any root carried by f.
func (f File) WithDefaults(name, tmpPattern, label string) File {
	return Spec{Name: name, TmpPattern: tmpPattern, Label: label}.Apply(f)
}

// Path returns the persisted file path.
func (f File) Path() string {
	return f.Root.Path(f.Name)
}

// Require validates the file root with the store-specific label.
func (f File) Require() error {
	return f.Root.Require(f.Label)
}

// Read decodes the persisted JSON file into value.
func (f File) Read(value any) error {
	return codec.ReadJSON(f.Path(), value)
}

// WriteAtomic marshals value as indented JSON and atomically replaces the
// persisted file.
func (f File) WriteAtomic(value any, writer codec.Writer) error {
	if err := f.Require(); err != nil {
		return err
	}
	return codec.WriteAtomicJSON(f.Root.String(), f.Name, f.TmpPattern, value, writer)
}

package codec

import (
	"os"
	"path/filepath"
	"testing"
)

type jsonFixture struct {
	Name string `json:"name"`
}

func TestReadJSONDecodesRequiredFile(t *testing.T) {
	root := t.TempDir()
	path := filepath.Join(root, "fixture.json")
	if err := os.WriteFile(path, []byte(`{"name":"raw"}`), 0o600); err != nil {
		t.Fatalf("write fixture: %v", err)
	}

	var got jsonFixture
	if err := ReadJSON(path, &got); err != nil {
		t.Fatalf("ReadJSON error: %v", err)
	}
	if got.Name != "raw" {
		t.Fatalf("Name = %q, want raw", got.Name)
	}
}

package decode

import (
	"errors"
	"testing"
)

type loadValueFixture struct {
	Name string `json:"name"`
}

type loadValueReader struct {
	value loadValueFixture
	err   error
}

func (r loadValueReader) Read(value any) error {
	if r.err != nil {
		return r.err
	}
	fixture, ok := value.(*loadValueFixture)
	if !ok {
		return errors.New("unexpected value type")
	}
	*fixture = r.value
	return nil
}

func TestLoadValueUsesEmptyValueAndEnsureHook(t *testing.T) {
	got, err := LoadValue(loadValueReader{value: loadValueFixture{Name: "raw"}}, func() loadValueFixture {
		return loadValueFixture{Name: "empty"}
	}, func(value loadValueFixture) loadValueFixture {
		value.Name += ":ensured"
		return value
	})
	if err != nil {
		t.Fatalf("LoadValue error: %v", err)
	}
	if got.Name != "raw:ensured" {
		t.Fatalf("LoadValue Name = %q, want ensured decoded value", got.Name)
	}
}

func TestLoadValueReturnsFreshEmptyValueOnReadError(t *testing.T) {
	got, err := LoadValue(loadValueReader{err: errors.New("read failed")}, func() loadValueFixture {
		return loadValueFixture{Name: "empty"}
	}, nil)
	if err == nil {
		t.Fatal("LoadValue error = nil, want read error")
	}
	if got.Name != "empty" {
		t.Fatalf("LoadValue value = %+v, want fresh empty value", got)
	}
}

package persisted

import "testing"

func TestSpecAppliesDefaultFileMetadataWhilePreservingRoot(t *testing.T) {
	spec := Spec{Name: "channel_directory.json", TmpPattern: ".channel_directory-*.tmp", Label: "channel directory"}

	file := spec.Apply(File{Root: NewRoot(" /tmp/gormes ")})

	if file.Root.String() != "/tmp/gormes" {
		t.Fatalf("Root = %q, want trimmed root", file.Root.String())
	}
	if file.Name != "channel_directory.json" || file.TmpPattern != ".channel_directory-*.tmp" || file.Label != "channel directory" {
		t.Fatalf("file metadata = %+v, want spec metadata", file)
	}
}

func TestSpecApplyKeepsConfiguredFile(t *testing.T) {
	spec := Spec{Name: "default.json", TmpPattern: ".default-*.tmp", Label: "default"}
	configured := File{Root: NewRoot("/tmp/custom"), Name: "custom.json", TmpPattern: ".custom-*.tmp", Label: "custom"}

	if got := spec.Apply(configured); got != configured {
		t.Fatalf("Apply configured = %+v, want %+v", got, configured)
	}
}

package readmodel

import (
	"errors"
	"os"
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/gateway/directory/model"
	"github.com/TrebuchetDynamics/gormes-agent/internal/gateway/directory/storage"
)

const channelDirectoryFileName = "channel_directory.json"

var channelDirectoryFileSpec = storage.Spec{Name: channelDirectoryFileName, TmpPattern: ".channel_directory-*.tmp", Label: "channel directory"}

// Directory is the channel-neutral cached read model for reachable messaging
// targets. It mirrors Hermes' channel_directory.json shape while keeping Gormes
// runtime behavior native Go and fixture-driven.
type Directory struct {
	UpdatedAt string                   `json:"updated_at,omitempty"`
	Platforms map[string][]model.Entry `json:"platforms"`
}

// Store persists channel_directory.json under a caller-owned Gormes state/home
// root. Tests pass temp roots; no live operator home is read.
type Store struct {
	file storage.File
}

// NewStore returns a store rooted at root.
func NewStore(root string) Store {
	return Store{file: channelDirectoryFileSpec.File(root)}
}

// NewDirectory returns a directory with initialized platform buckets.
func NewDirectory(updatedAt string) Directory {
	return Directory{UpdatedAt: strings.TrimSpace(updatedAt), Platforms: model.EmptyPlatformBuckets[model.Entry]()}
}

// UpsertEntries normalizes a platform bucket and merges complete target entries
// into the directory. It is the shared merge contract for adapter inventory and
// remembered-source refresh contributions.
func (d *Directory) UpsertEntries(platform string, entries ...model.Entry) int {
	d.Platforms = model.EnsurePlatformBuckets(d.Platforms)
	platform = model.NormalizePlatform(platform)
	if platform == "" {
		return 0
	}
	merged := 0
	for _, entry := range entries {
		var ok bool
		d.Platforms[platform], ok = model.UpsertValidEntry(d.Platforms[platform], entry)
		if ok {
			merged++
		}
	}
	return merged
}

// Root returns the store root for fixture setup.
func (s Store) Root() string { return s.jsonFile().Root.String() }

func (s Store) jsonFile() storage.File {
	return channelDirectoryFileSpec.Apply(s.file)
}

// Load reads the directory. Missing or invalid files return empty directories
// plus structured degraded evidence.
func (s Store) Load() (Directory, model.Evidence) {
	dir, err := storage.LoadValue(s.jsonFile(), emptyDirectory, ensureDirectory)
	if errors.Is(err, os.ErrNotExist) {
		return emptyDirectory(), model.Evidence{Code: model.EvidenceChannelDirectoryMissing}
	} else if err != nil {
		return emptyDirectory(), model.Evidence{Code: model.EvidenceChannelDirectoryInvalid}
	}
	return dir, model.Evidence{}
}

// Save atomically writes the directory.
func (s Store) Save(dir Directory) error {
	return s.SaveWithWriter(dir, os.WriteFile)
}

// SaveWithWriter exists for deterministic atomic-write failure tests. It writes
// a temp file, then renames only after the writer succeeds, so old complete JSON
// remains visible after an injected partial-write failure.
func (s Store) SaveWithWriter(dir Directory, writer func(string, []byte, os.FileMode) error) error {
	if writer == nil {
		writer = os.WriteFile
	}
	dir.Platforms = model.EnsurePlatformBuckets(dir.Platforms)
	return s.jsonFile().WriteAtomic(dir, storage.Writer(writer))
}

func emptyDirectory() Directory {
	return NewDirectory("")
}

func ensureDirectory(dir Directory) Directory {
	return normalizeDecodedDirectory(dir)
}

// normalizeDecodedDirectory is the load-time value contract for persisted
// directory JSON. Adapter refreshes already upsert normalized entries; decoded
// operator-edited or older cache files need the same platform/field trimming so
// lookup, display, and stale-target validation all see one canonical shape.
func normalizeDecodedDirectory(dir Directory) Directory {
	dir.UpdatedAt = strings.TrimSpace(dir.UpdatedAt)
	platforms := model.EmptyPlatformBuckets[model.Entry]()
	for platform, entries := range model.EnsurePlatformBuckets(dir.Platforms) {
		platform = model.NormalizePlatform(platform)
		if platform == "" {
			continue
		}
		for _, entry := range entries {
			platforms[platform] = append(platforms[platform], model.NormalizeEntry(entry))
		}
	}
	dir.Platforms = platforms
	return dir
}

package sources

import (
	"context"
	"os"
	"time"

	"github.com/TrebuchetDynamics/gormes-agent/internal/gateway/directory/model"
	"github.com/TrebuchetDynamics/gormes-agent/internal/gateway/directory/storage"
)

const channelDirectorySourcesFileName = "channel_directory_sources.json"

var channelDirectorySourcesFileSpec = storage.Spec{Name: channelDirectorySourcesFileName, TmpPattern: ".channel_directory_sources-*.tmp", Label: "channel directory source"}

// RememberedStore is the fakeable ledger seam used by Manager to persist
// allowed inbound channel sources without mutating channel_directory.json. A
// later refresh slice can merge this ledger into the directory read model.
type RememberedStore interface {
	RememberSource(context.Context, model.RememberedSourceEntry) error
}

// Store persists a remembered-source ledger under a caller-owned root. It is
// distinct from channel_directory.json on purpose.
type Store struct {
	file storage.File
	now  func() time.Time
}

func NewStore(root string) Store {
	return Store{file: channelDirectorySourcesFileSpec.File(root), now: time.Now}
}

func (s Store) jsonFile() storage.File {
	return channelDirectorySourcesFileSpec.Apply(s.file)
}

func (s Store) loadFile() (storage.File, bool) {
	file := s.jsonFile()
	if file.Require() != nil {
		return storage.File{}, false
	}
	return file, true
}

// Load reads the remembered-source ledger. Missing ledgers are not failures;
// they simply contribute no session-discovered entries during refresh.
func (s Store) Load() (model.RememberedSourceLedger, model.Evidence) {
	file, ok := s.loadFile()
	if !ok {
		return model.EmptyRememberedSourceLedger(), model.Evidence{}
	}
	ledger, err := storage.LoadValue(file, model.EmptyRememberedSourceLedger, model.EnsureRememberedSourceLedger)
	if err != nil {
		if os.IsNotExist(err) {
			return model.EmptyRememberedSourceLedger(), model.Evidence{}
		}
		return model.EmptyRememberedSourceLedger(), model.Evidence{Code: model.EvidenceChannelDirectorySourcesInvalid}
	}
	return ledger, model.Evidence{}
}

func (s Store) RememberSource(_ context.Context, entry model.RememberedSourceEntry) error {
	if err := s.jsonFile().Require(); err != nil {
		return err
	}
	entry = model.NormalizeRememberedSourceEntry(entry)
	if entry.Platform == "" || entry.ID == "" {
		return nil
	}
	ledger := model.EmptyRememberedSourceLedger()
	_ = s.jsonFile().Read(&ledger)
	ledger = model.EnsureRememberedSourceLedger(ledger)
	if s.now == nil {
		s.now = time.Now
	}
	now := s.now().UTC().Format(time.RFC3339Nano)
	entry.UpdatedAt = now
	ledger.UpdatedAt = now
	ledger.Platforms[entry.Platform], _ = model.UpsertRememberedSourceEntry(ledger.Platforms[entry.Platform], entry)
	return s.save(ledger)
}

func (s Store) save(ledger model.RememberedSourceLedger) error {
	return s.jsonFile().WriteAtomic(ledger, nil)
}

